#include <stdlib.h>

#define MAXN 300005
#define INF 2000000000000000000LL

typedef struct {
    long long u;
    long long v;
} Point;

Point pts[MAXN];
int N;
long long min_u_all, max_u_all;
long long min_v_all, max_v_all;

int check(long long D) {
    // Caso 1: B1 cobre o canto (min_u, min_v)
    // B1: u in [min_u_all, min_u_all + D], v in [min_v_all, min_v_all + D]
    long long lim_u1 = min_u_all + D;
    long long lim_v1 = min_v_all + D;

    long long b_min_u = INF, b_max_u = -INF;
    long long b_min_v = INF, b_max_v = -INF;

    for (int i = 0; i < N; i++) {
        if (pts[i].u > lim_u1 || pts[i].v > lim_v1) {
            if (pts[i].u < b_min_u) b_min_u = pts[i].u;
            if (pts[i].u > b_max_u) b_max_u = pts[i].u;
            if (pts[i].v < b_min_v) b_min_v = pts[i].v;
            if (pts[i].v > b_max_v) b_max_v = pts[i].v;
        }
    }

    if (b_min_u == INF || (b_max_u - b_min_u <= D && b_max_v - b_min_v <= D)) {
        return 1;
    }

    // Caso 2: B1 cobre o canto (min_u, max_v)
    // B1: u in [min_u_all, min_u_all + D], v in [max_v_all - D, max_v_all]
    long long lim_u2 = min_u_all + D;
    long long lim_v2 = max_v_all - D;

    b_min_u = INF; b_max_u = -INF;
    b_min_v = INF; b_max_v = -INF;

    for (int i = 0; i < N; i++) {
        if (pts[i].u > lim_u2 || pts[i].v < lim_v2) {
            if (pts[i].u < b_min_u) b_min_u = pts[i].u;
            if (pts[i].u > b_max_u) b_max_u = pts[i].u;
            if (pts[i].v < b_min_v) b_min_v = pts[i].v;
            if (pts[i].v > b_max_v) b_max_v = pts[i].v;
        }
    }

    if (b_min_u == INF || (b_max_u - b_min_u <= D && b_max_v - b_min_v <= D)) {
        return 1;
    }

    return 0;
}

static long long X[MAXN];

int main() {
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%lld", &X[i]);
    }

    min_u_all = INF; max_u_all = -INF;
    min_v_all = INF; max_v_all = -INF;

    for (int i = 0; i < N; i++) {
        long long y;
        scanf("%lld", &y);
        pts[i].u = X[i] + y;
        pts[i].v = X[i] - y;

        if (pts[i].u < min_u_all) min_u_all = pts[i].u;
        if (pts[i].u > max_u_all) max_u_all = pts[i].u;
        if (pts[i].v < min_v_all) min_v_all = pts[i].v;
        if (pts[i].v > max_v_all) max_v_all = pts[i].v;
    }

    long long low = 0, high = 2000000000LL;
    long long ans = high;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    printf("%lld\n", ans);

    return 0;
}
